{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Tiotropium, a quaternary ammonium scopine ester with the same tropane-epoxide scaffold and permanent positive charge, has absolute oral bioavailability of only 2–3% in healthy volunteers, directly demonstrating poor absorption for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Ipratropium, a quaternary ammonium tropane ester of tropic acid, has absolute oral bioavailability of about 2% across multiple healthy-volunteer studies, confirming the low-F phenotype for quaternary ammonium tropane esters.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Cyclandelate, the highest-transfer comparator sharing the phenyl-hydroxy-ester motif, showed extremely low bioavailability in humans, supporting poor systemic exposure for this ester class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Tilidine, a tertiary amine phenyl-ester with high transfer score, had systemic bioavailability of only 3–7.6% in humans due to extensive first-pass metabolism, supporting low F for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Phenoperidine, another high-transfer tertiary amine ester, had oral bioavailability below 15% in healthy subjects, further supporting the low-F pattern.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a quaternary ammonium tropane ester (N-ethyl-N-methylscopolamine). Direct quaternary ammonium analogs tiotropium and ipratropium have absolute oral bioavailability of 2–3%, and high-transfer tertiary amine esters (tilidine, phenoperidine, cyclandelate) also show low F. The permanent positive charge and ester/tropane scaffold dominate absorption; high-F tertiary amine comparators lack the quaternary charge and are not transferable. Therefore F < 20% is strongly supported.",
  "evidence_gaps": [
    "No direct human absolute F measurement for the exact query molecule.",
    "The closest quaternary analogs have low-to-moderate assay-transfer scores, so extrapolation relies on structural analogy.",
    "One ipratropium record (C43) reports ~32% F, inconsistent with multiple 2–3% studies; its methodology and interpretation are uncertain.",
    "No specific data on intestinal efflux or active secretion for the query molecule."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

